function truncateUtf8(s: string, limitBytes: number): string {
  const enc = new TextEncoder();
  let used = 0;
  let out = "";
  for (const ch of s) { // iterates code points, not bytes
    const n = enc.encode(ch).length;
    if (used + n > limitBytes) break;
    used += n;
    out += ch;
  }
  return out;
}
const stored = truncateUtf8(title, limitBytes);
